import br.tcc.checkout.util.Arredondador;
import java.math.BigDecimal;
import java.util.List;

public class CupomLeve3Pague2 implements Cupom {
    @Override
    public String getCodigo() {
        return "LEVE3PAGUE2";
    }

    @Override
    public boolean ehAplicavel(BigDecimal subtotalProdutos, BigDecimal pesoTotalKg) {
        return true;
    }

    @Override
    public BigDecimal calcularDesconto(BigDecimal subtotalProdutos, List<Integer> quantidadesPorItem) {
        return Arredondador.arredondarParaCentavos(calcularDescontoLeve3(quantidadesPorItem));
    }

    private BigDecimal calcularDescontoLeve3(List<Integer> quantidadesPorItem) {
        BigDecimal desconto = BigDecimal.ZERO;
        for (int i = 0; i < quantidadesPorItem.size(); i++) {
            int quantidade = quantidadesPorItem.get(i);
            int unidadesGratis = quantidade / 3;
            if (unidadesGratis > 0) {
                BigDecimal precoUnitario = BigDecimal.ZERO;
                desconto = desconto.add(precoUnitario.multiply(new BigDecimal(unidadesGratis)));
            }
        }
        return desconto;
    }
}

